#' Machine-readable contract for the development RDS envelope
#' @return A list suitable for JSON serialization; this is an RDS profile, not a JSON transport.
#' @export
splitaligner_exchange_schema <- function() {
  list(schema_id = "SplitAlignerR.exchange", schema_version = .sx_version, profile = .sx_profile,
       status = "DEVELOPMENT_INTERFACE_NOT_RELEASE_CERTIFICATION",
       transport = list(format = "RDS", serialization_version = 3L,
                        content_hash = .sx_hash_schema,
                        hash_runtime_acceptance = "R4.4.2 arm64 C and en_US.UTF-8; actual cross-R-version acceptance pending",
                        hash_definition = "SHA256 of SAR-C14N-1 typed recursive canonical bytes; no R serialization metadata; see HASH_CONTRACT_H01_PROPOSAL_R1.md; outer RDS file SHA is separate"),
       required_top_level_fields = c(.sx_components, "manifest"),
       field_types = list(schema = "named list id/version/profile", producer = "package/version/core_version/source list",
                          contract = "mode/payload/state/split/numeric contract list", axes = "orientation/branch_margin/gene_ids/coordinate_ids list",
                          identity = "six explicit coordinate, tree and ordered ledger identities",
                          tree = "complete phylo, explicit source, ordered taxon ledger",
                          coordinates = "ordered primitive data.frame with taxon-array list columns",
                          labels = "registry/native/active scheme and ledgers; ordered migration provenance",
                          data = "six identically keyed matrices", preserved = "exact original result and complete state/composite/gene ledgers",
                          annotation = "tree-instance edge table and separate root metadata", manifest = "component_sha256 and content_sha256"),
       axes = list(default_orientation = "gene_by_branch", default_branch_margin = 2L,
                   alternate_orientation = "branch_by_gene", alternate_branch_margin = 1L,
                   explicit_transpose_api = "transpose_splitaligner_exchange", infer_from_dimensions = FALSE,
                   matrix_names = c("values", "coord_state", "value_reason", "source_state", "source_reason", "numeric_status")),
       state_mapping = list(mapped_finite = list(coord_state = "observed", value = "exact finite double including zero/negative", value_reason = "NA_character_"),
                            mapped_unavailable = list(coord_state = "observed", value = "NA_real_", value_reason = "exact numeric_status"),
                            NA_struct = list(coord_state = "NA_struct", value = "NA_real_", value_reason = "NA_character_"),
                            NA_fuse = list(coord_state = "NA_fuse", value = "NA_real_", value_reason = "NA_character_"),
                            NA_topo = list(coord_state = "NA_topo", value = "NA_real_", value_reason = "NA_character_")),
       reasons = list(source_reason = "exact state_ledger reason_code; never discarded", numeric_status = "exact state_ledger numeric_status"),
       payload = list(required = c("type", "name", "units", "scale", "origin", "spec_id"), type = "branch_length", scale = "identity",
                      negative_finite_values = "preserved by exporter; LT public S2 must reject separately"),
       coordinates = list(identity = "SAR2:SHA256 of key schema, taxon-domain SHA and opaque producer key",
                           key_schema = "SplitAligner-canonical-split-key-v2", parse_key_delimiters = FALSE,
                           columns = c("coordinate_id", "canonical_split_key", "key_schema", "source_alias", "coordinate_type", "branch_type",
                                       "terminal_taxon", "side_A_taxa", "side_B_taxa", "representation_aliases"),
                           side_columns_R_type = "AsIs list columns of character arrays", B_alias_is_scientific_identity = FALSE),
       label_registry = splitaligner_label_registry(),
       tree_mapping = list(profile = "exact unique exhaustive primitive-to-phylo-edge bijection", mapping = "explicit taxon sets; no split-key parsing",
                            root_has_ordinary_incoming_edge = FALSE, tree_instance_identity = "complete phylo object hash",
                            geometry_column = "tree_branch_length", selected_gene_column = "gene_branch_value",
                            node = "child_node in this tree instance only", composite_as_ordinary_edge = FALSE,
                            automatic_reroot_prune_merge = FALSE),
       API = c("export_splitaligner_exchange", "read_splitaligner_exchange", "validate_splitaligner_exchange",
               "transpose_splitaligner_exchange", "annotate_splitaligner_exchange", "splitaligner_label_registry",
               "new_splitaligner_label_migration", "migrate_splitaligner_labels"),
       unsupported = c("free", "paired", "unknown mode/payload/scheme/provenance", "root or edge non-bijection",
                       "whole-history legacy certification", "implicit axis repair"),
       handoff_scope = "S1 producer interface; actual LT reader and ape/ggtree joint acceptance are S2, not yet run")
}
